catalog_script_client.script:
function onLoad() {
    var userId = g_user.userID;
    if (g_user.roles.indexOf('x_hsb11_mss_custod.custody_maker') > -1) {
        g_form.setValue('assigned_to', userId);

        g_form.addOption('table', '', '--None--');
        g_form.setValue('table', '');

        g_form.setDisplay('state', false);
        g_form.setDisplay('stage', false);

        hideInitialFields();

    } else {
        g_form.setMandatory('table', false);
        g_form.setReadOnly('table', true);
    }
    // g_form.setValue('assigned_to', userId);

    // g_form.addOption('table', '', '--None--');
    // g_form.setValue('table', '');

    function hideInitialFields() {
        var fieldsToHideInitial = getFieldsToHideInitial();
        fieldsToHideInitial.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function getFieldsToHideInitial() {
        return [
            'action',

            'owning_business',

            'old_reason_code', 'reason_code', 'new_reason_code',
            'old_reason_code_label', 'reason_code_label', 'new_reason_code_label',
            'old_reason_code_type', 'reason_code_type',
            'old_reason_description', 'reason_description',
            'old_reason_dashboard_group', 'reason_dashboard_group',

            'old_location_code', 'location_code', 'new_location_code',
            'old_location_description', 'location_description', 'new_location_description',
            'old_region', 'region', 'new_region',

            'old_local_limit', 'local_limit', 'new_local_limit',
            'old_currency', 'currency', 'new_currency',
            'old_band_group', 'band_group', 'new_band_group'
        ];

    }





}
